fn solve(n: i8, s: Vec<char>) -> i8 {
    // Coordinates
    let mut x = 0;
    let mut y = 0;
    // last_region: 0 = on border or not visited any region yet,
    //              1 = region A (x > y),
    //              2 = region B (y > x)
    let mut last_region = 0;
    // Count of transitions between region A and B
    let mut transitions: i8 = 0;

    for &c in &s {
        // Apply the move
        match c {
            'U' => y += 1,
            'R' => x += 1,
            _ => unreachable!("Invalid move character"),
        }

        // Determine current region
        let region = if x > y {
            1
        } else if y > x {
            2
        } else {
            0
        };

        // If we're in a strict region (not on the border):
        // - If we have a last_region != 0 and it's different from the current one,
        //   that's a transition.
        // - If last_region == 0, this is just the initial entry into a region and
        //   does not count as a transition.
        if region != 0 {
            if last_region != 0 && last_region != region {
                transitions += 1;
            }
            last_region = region;
        }
        // If region == 0, we stay on the border and do not change last_region nor count a transition.
    }

    transitions
}

